// SPDX-License-Identifier: Apache-2.0
//
// Multi-particle test for the Broms MFS Stokes mobility solver against the
// large-scale ellipsoid CSV reference
// (mfs/ellipsoid_mobility_p1000_delta0p2_nv34.csv): P=1000 identical triaxial
// ellipsoids (semiaxes E0=[0.4 0.6 1.0]) in a dense delta=0.2 cluster, each
// with its own random orientation R_k and a random applied wrench (force +
// torque). The CSV was produced by the MATLAB StokesMFS3D pipeline
// (getEllipsoidGrids + solve_mobility, FMM3D far field at eps=1e-8); it gives
// the reference rigid-body velocities (v, w) per particle, which we compare to.
//
// Geometry: the solver is monodisperse -- one reference cloud (particle 0,
// centered at the origin in the reference orientation) is rotated+translated to
// every particle. The reference clouds are the SAME ones the MATLAB generator
// built, regenerated by mfs/gen_ellipsoid_clouds.m:
//   collocation X_ref = b_outer.x                       (864 points, on surface)
//   source      Y_ref = b_inner.x - b_inner.nx*sep      (656 points, inside; sep=0.125)
// and per-particle placement t_k + R_k*base matches tileRotateTranslate exactly.
// Kernel convention G=(1/8pi)(I/r + rr^T/r^3), mu=1, matches MATLAB + FMM3D.
//
// CSV columns (42): particle_id, total_particles, paper_reference_particles,
// delta, Nv, N1, sep, rng_seed, source_points_per_particle,
// collocation_points_per_particle, gmres_tol, fmm_eps, gmres_iterations,
// lambda_norm_inf, max_surface_residual, semiaxis_a/b/c, center_x/y/z,
// rotation_r11..r33 (ROW-MAJOR R_k), force_x/y/z, torque_x/y/z,
// velocity_x/y/z, angular_velocity_x/y/z.

#include "mfs_broms.cuh"

#include <chrono>

struct Row {
  double c[3], R[9], f[3], t[3], v[3], w[3];
};

// Supports two CSV layouts (auto-detected by column count):
//   42 cols: mobility result -- ...,center(18),R(21..29),force(30),torque(33),
//            velocity(36),angular_velocity(39)  -> reference v/w available.
//   27 cols: config only      -- ...,center(9),R(12..20),force(21),torque(24)
//            -> NO reference velocities (perf-only). v/w left zero.
// hasRef is set to whether reference velocities were parsed.
static std::vector<Row> loadCSV(const std::string &path, bool &hasRef)
{
  std::ifstream in(path);
  if (!in) { std::fprintf(stderr, "cannot open %s\n", path.c_str()); std::exit(1); }
  std::vector<Row> rows;
  std::string line;
  std::getline(in, line);  // header
  int ncol = 1;
  for (char ch : line) if (ch == ',') ++ncol;
  hasRef = (ncol >= 42);
  const int cOff = hasRef ? 18 : 9;    // center
  const int rOff = hasRef ? 21 : 12;   // rotation r11..r33 (row-major)
  const int fOff = hasRef ? 30 : 21;   // force
  const int tOff = hasRef ? 33 : 24;   // torque
  const int need = hasRef ? 42 : 27;
  while (std::getline(in, line)) {
    if (line.empty()) continue;
    for (char &ch : line) if (ch == ',') ch = ' ';
    std::istringstream ss(line);
    std::vector<double> a(need);
    bool ok = true;
    for (int i = 0; i < need; ++i) if (!(ss >> a[i])) { ok = false; break; }
    if (!ok) continue;
    Row r{};
    for (int d = 0; d < 3; ++d) {
      r.c[d] = a[cOff + d];
      r.f[d] = a[fOff + d];
      r.t[d] = a[tOff + d];
      if (hasRef) { r.v[d] = a[36 + d]; r.w[d] = a[39 + d]; }
    }
    for (int e = 0; e < 9; ++e) r.R[e] = a[rOff + e];
    rows.push_back(r);
  }
  return rows;
}

int main(int argc, char **argv)
{
  //std::string csvPath = "mfs/ellipsoid_mobility_p1000_delta0p2_nv34.csv";
  std::string csvPath = "mfs/ellipsoid_config_p10000_delta0p2_nv34.csv";
  std::string bPath = "mfs/points/b_ellipsoid_p1000.txt";  // collocation (M)
  std::string sPath = "mfs/points/s_ellipsoid_p1000.txt";  // source      (N)

  bool useTreecode = false;                 // default brute; --treecode to enable
  MFSTreecode<>::Config tcCfg;              
  double kspRtol = 1e-7;                    // treecode KSP rtol (fp32 floor ~1e-6)

  std::vector<char *> petscArgv{argv[0]};
  for (int i = 1; i < argc; ++i) {
    std::string a = argv[i];
    auto val = [&](const char *k) { return a.substr(std::string(k).size()); };
    if (a.rfind("--csv=", 0) == 0) csvPath = val("--csv=");
    else if (a.rfind("--collocation=", 0) == 0) bPath = val("--collocation=");
    else if (a.rfind("--source=", 0) == 0) sPath = val("--source=");
    else if (a == "--treecode") useTreecode = true;
    else if (a == "--brute") useTreecode = false;
    else if (a.rfind("--tc-mac=", 0) == 0) tcCfg.mac = (float)std::atof(val("--tc-mac=").c_str());
    else if (a.rfind("--tc-cell=", 0) == 0) tcCfg.cellEdge = std::atof(val("--tc-cell=").c_str());
    else if (a.rfind("--tc-maxleaf=", 0) == 0) tcCfg.maxLeaf = std::atoi(val("--tc-maxleaf=").c_str());
    else if (a.rfind("--ksp-rtol=", 0) == 0) kspRtol = std::atof(val("--ksp-rtol=").c_str());
    else petscArgv.push_back(argv[i]);
  }
  int pArgc = (int)petscArgv.size();
  char **pArgv = petscArgv.data();
  PetscCall(PetscInitialize(&pArgc, &pArgv, nullptr, nullptr));

  cublasHandle_t cublas;
  cusolverDnHandle_t solver;
  CUBLAS_CHECK(cublasCreate(&cublas));
  CUSOLVER_CHECK(cusolverDnCreate(&solver));

  // ---- reference data + base clouds ----
  bool hasRef = false;
  std::vector<Row> rows = loadCSV(csvPath, hasRef);
  const int P = (int)rows.size();
  int M, N;
  std::vector<double> Xref = loadPointsASCII(bPath, M);  // collocation, 3*M
  std::vector<double> Yref = loadPointsASCII(sPath, N);  // source,      3*N

  // ---- per-particle state from the CSV ----
  std::vector<double> centers(3 * P), F(3 * P), T(3 * P), R((size_t)P * 9);
  for (int k = 0; k < P; ++k) {
    for (int d = 0; d < 3; ++d) {
      centers[3 * k + d] = rows[k].c[d];
      F[3 * k + d] = rows[k].f[d];
      T[3 * k + d] = rows[k].t[d];
    }
    for (int e = 0; e < 9; ++e) R[(size_t)k * 9 + e] = rows[k].R[e];
  }

  std::printf("P=%d ellipsoids (E0=[0.4 0.6 1.0]), M=%d collocation, N=%d source, "
              "n=%lld unknowns%s\n", P, M, N, 3LL * M * P,
              hasRef ? "" : "  [perf-only: no reference velocities]");
  std::printf("Stokeslet eval: %s\n",
              useTreecode ? "TREECODE" : "brute O(P^2*M*N)");
  if (useTreecode)
    std::printf("  tc: %s mac=%.3f cellEdge=%s maxLeaf=%d\n",
                MFSTreecode<>::multipoleName(),
                tcCfg.mac, tcCfg.cellEdge > 0 ? std::to_string(tcCfg.cellEdge).c_str() : "auto",
                tcCfg.maxLeaf);

  // ---- setup + one solve (timed) ----
  auto t0 = std::chrono::steady_clock::now();
  MFSContext *m = mfsSetup(cublas, solver, P, M, N, Xref.data(), Yref.data(), 1.0);
  if (useTreecode) mfsSetTreecode(m, tcCfg, kspRtol);
  CUDA_CHECK(cudaDeviceSynchronize());
  auto t1 = std::chrono::steady_clock::now();
  std::vector<double> U;
  mfsSolve(m, centers.data(), R.data(), F.data(), T.data(), U);
  CUDA_CHECK(cudaDeviceSynchronize());
  auto t2 = std::chrono::steady_clock::now();
  auto ms = [](auto a, auto b) {
    return std::chrono::duration<double, std::milli>(b - a).count();
  };
  std::printf("\nsetup %.0f ms, solve %.0f ms  (%.2f s total)\n",
              ms(t0, t1), ms(t1, t2), ms(t0, t2) / 1e3);
  if (useTreecode) {
    const auto &st = m->tc->stats();
    std::printf("treecode interactions: near pairs = %lld, direct P2P = %lld\n",
                st.nPairs, st.totalP2P);
  }
  auto finish = [&](int code) -> int {
    const bool trace = mfsEnvFlag("MFS_DESTROY_TRACE", false);
    auto mark = [trace](const char *what) {
      if (trace) {
        std::fprintf(stderr, "[test_mfs_ellipsoid cleanup] %s\n", what);
        std::fflush(stderr);
      }
    };
    mark("mfsDestroy");
    mfsDestroy(m);
    mark("cublasDestroy");
    cublasDestroy(cublas);
    mark("cusolverDnDestroy");
    cusolverDnDestroy(solver);
    const bool skipPetsc = mfsSkipPetscTeardownForProfiler();
    if (!skipPetsc) {
      mark("PetscFinalize");
      PetscCall(PetscFinalize());
    } else {
      mark("skip PetscFinalize under Nsight CUDA memory tracking");
      std::fflush(stdout);
      std::fflush(stderr);
      std::_Exit(code);
    }
    mark("return");
    return code;
  };

  if (!hasRef) {
    // perf-only: no reference to compare against. Show a couple of computed
    // rigid-body velocities as a sanity peek and exit success.
    std::printf("\nperf-only run (config CSV has no reference velocities)\n");
    for (int k = 0; k < P && k < 4; ++k)
      std::printf("  particle %d: v=(%+.4f %+.4f %+.4f)  w=(%+.4f %+.4f %+.4f)\n",
                  k, U[6 * k], U[6 * k + 1], U[6 * k + 2],
                  U[6 * k + 3], U[6 * k + 4], U[6 * k + 5]);
    return finish(0);
  }

  // ---- compare (max + full rel-L2, split into v and w) ----
  double maxV = 0, maxW = 0, refVmax = 0, refWmax = 0;
  double nV2 = 0, nW2 = 0, dV2 = 0, dW2 = 0;
  int kV = 0, kW = 0;
  for (int k = 0; k < P; ++k) {
    for (int d = 0; d < 3; ++d) {
      double ev = U[6 * k + d] - rows[k].v[d];
      double ew = U[6 * k + 3 + d] - rows[k].w[d];
      if (std::fabs(ev) > maxV) { maxV = std::fabs(ev); kV = k; }
      if (std::fabs(ew) > maxW) { maxW = std::fabs(ew); kW = k; }
      refVmax = std::max(refVmax, std::fabs(rows[k].v[d]));
      refWmax = std::max(refWmax, std::fabs(rows[k].w[d]));
      dV2 += ev * ev; nV2 += rows[k].v[d] * rows[k].v[d];
      dW2 += ew * ew; nW2 += rows[k].w[d] * rows[k].w[d];
    }
  }

  std::printf("\n%4s | %12s %12s %12s | %12s %12s %12s\n", "k", "v_x(mine)",
              "v_x(ref)", "dv_x", "w_x(mine)", "w_x(ref)", "dw_x");
  for (int k = 0; k < P && k < 6; ++k)
    std::printf("%4d | %12.6f %12.6f %12.3e | %12.6f %12.6f %12.3e\n", k,
                U[6 * k], rows[k].v[0], U[6 * k] - rows[k].v[0],
                U[6 * k + 3], rows[k].w[0], U[6 * k + 3] - rows[k].w[0]);

  std::printf("\nvelocity     : max|dv| = %.3e (particle %d), max|v_ref| = %.3e -> rel %.3e | rel-L2 %.3e\n",
              maxV, kV, refVmax, maxV / refVmax, std::sqrt(dV2 / nV2));
  std::printf("angular vel  : max|dw| = %.3e (particle %d), max|w_ref| = %.3e -> rel %.3e | rel-L2 %.3e\n",
              maxW, kW, refWmax, maxW / refWmax, std::sqrt(dW2 / nW2));

  bool pass = (maxV / refVmax < 1e-2) && (maxW / refWmax < 1e-2);
  std::printf("\n%s\n", pass ? "PASS (within 1% of reference)" : "MISMATCH");

  return finish(pass ? 0 : 1);
}
